def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 80:
                    dangerous_prev.append(bid)

    if not alive:
        return max(0, min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if slots >= 2:
        urgency -= 1
    else:
        urgency += 1

    if day >= 8:
        urgency += 1

    if budget <= DAILY_SALARY * 1.2:
        urgency += 1

    if urgency <= 0:
        base = 22.0 if slots >= 2 else 34.0
    elif urgency == 1:
        base = 36.0 if slots >= 2 else 52.0
    elif urgency == 2:
        base = 52.0 if slots >= 2 else 71.0
    elif urgency == 3:
        base = 69.0 if slots >= 2 else 88.0
    else:
        base = 92.0 if slots >= 2 else 111.0

    if highest_prev >= 110:
        if urgency >= 3:
            bid = max(base, highest_prev + 1.0)
        else:
            bid = min(base, 45.0)
    elif highest_prev >= 95:
        if urgency >= 2:
            bid = max(base, highest_prev + 1.5)
        else:
            bid = min(base, 50.0)
    elif highest_prev >= 75:
        bid = max(base, highest_prev + 1.0)
    elif highest_prev > 0:
        bid = max(base, avg_prev + 2.0)
    else:
        bid = base

    rich_opponents = 0
    for opp in alive:
        if opp.get('budget', 0) >= 800:
            rich_opponents += 1
    if rich_opponents >= 2 and urgency >= 2:
        bid += 4.0

    if slots >= 2 and urgency <= 1:
        bid -= 6.0

    if hp <= 1 or no_water_days >= 2:
        bid = max(bid, 118.0)

    if budget < bid:
        bid = budget

    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Identify alive opponents and compute yesterday bid pressure
    alive_opps = [o for o in opponents_status.values() if o.get('alive')]

    # If no opponents are alive, conserve budget
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply factor: more supply -> less aggressive; less supply -> more aggressive
    # Ensure indices are integers if we ever use arrays (we won't).
    s = float(supply)
    if s <= MIN_SUPPLY:
        supply_factor = 1.0
    elif s >= MAX_SUPPLY:
        supply_factor = 0.75
    else:
        # Linear interpolation between 1.0 at MIN_SUPPLY and 0.75 at MAX_SUPPLY
        supply_factor = 1.0 - 0.25 * ((s - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If my hp is critical or I'm already accumulating no-water days, bid hard.
    if my_hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.95
    else:
        # Use yesterday's observed pressure to decide baseline.
        # Cindy/Eric surviving with high bids implies we need to stay competitive.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * 0.55
        else:
            target = DAILY_SALARY * 0.45

    # Adjust by supply factor and slightly counteract high previous bids
    # If others were bidding extremely high, we increase a bit; if not, keep moderate.
    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 1.05:
            target *= 1.10
        elif highest_prev_bid >= DAILY_SALARY * 0.85:
            target *= 1.00
        else:
            target *= 0.95

    target *= supply_factor

    # Never bid more than budget; also clamp to a reasonable range.
    # In this game, bids appear around 0..120 in traces.
    bid = min(my_budget, max(0.0, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None and prev_trace['bid'] > 0:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = 0.0

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.85
    else:
        if yesterday_bids:
            max_prev_bid = max(yesterday_bids)
            if max_prev_bid >= DAILY_SALARY * 0.8:
                base_bid = min(DAILY_SALARY * 0.9, max_prev_bid + 2.0)
            elif max_prev_bid >= DAILY_SALARY * 0.6:
                base_bid = max_prev_bid + 1.5
            else:
                base_bid = DAILY_SALARY * 0.65
        else:
            base_bid = DAILY_SALARY * 0.6

    final_bid = max(1.0, base_bid)
    final_bid = min(final_bid, my_status['budget'])

    return final_bid

